import {elapsedYearLabel} from './elapsed-year.mjs';
import {calculateSavings,savingsDividendLabel} from './savings-calculator.mjs';
import {createSavingsExcel,createSavingsPDF,SAVINGS_DISCLAIMER} from './savings-report.mjs';
const $=id=>document.getElementById(id),money=n=>n.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});
let current=null,mode='sum',exporting=false;
const originalText=Object.fromEntries(['life-note','maturity-note','table-note'].map(id=>[id,$(id).textContent]));
function render(){
 const superSaver=$('plan').value==='super2516',endowment=$('plan').value==='endowment2014',happy=$('plan').value==='happy2010',modal=superSaver||endowment||happy,guaranteed=modal||$('plan').value==='guaranteed',payYears=superSaver?16:endowment?14:happy?10:6,term=superSaver?25:modal?20:15,cashYears=superSaver?24:endowment?0:happy?19:guaranteed?14:7;
 $('frequency-field').hidden=!modal;$('frequency').disabled=!modal;
 $('gender-rate-note').textContent=(superSaver||endowment)?'ใช้อัตราเบี้ยตามเพศและอายุที่เลือก':'ทั้งสองเพศใช้อัตราเบี้ยเดียวกัน';
 $('days-label').textContent=endowment?'อายุอย่างน้อย 1 เดือน':'อายุอย่างน้อย 30 วัน';
 $('frequency-note').textContent=modal?'ใช้อัตรารายงวดตามภาพ · ไม่มีส่วนลดเบี้ยรายปี':'ชำระรายปีเท่านั้น · ไม่มีส่วนลดเบี้ยรายปี';
 $('age').max=(superSaver||endowment)?'65':happy?'75':'80';$('term-badge').textContent=superSaver?'25/16':endowment?'20/14':happy?'20/10':'15/6';$('term-description').innerHTML=`ชำระเบี้ย ${payYears} ปี<br><strong>คุ้มครอง ${term} ปี</strong>`;$('schedule-duration').textContent=`ตลอดระยะเวลา ${term} ปี`;
 $('days-field').hidden=(!endowment&&guaranteed)||$('age').value!== '0';$('age-note').textContent=superSaver?'อายุในตารางอัตราเบี้ย 0–65 ปี':endowment?'รับประกันอายุ 1 เดือน–65 ปี':happy?'อายุในตารางอัตราเบี้ย 0–75 ปี':guaranteed?'อายุในตารางอัตราเบี้ย 0–80 ปี':'รับประกันอายุ 30 วัน–80 ปี';
 $('index-box').hidden=guaranteed;$('simulate').disabled=guaranteed;
 $('dividend-column').hidden=guaranteed;$('index-formula').hidden=$('index-note').hidden=guaranteed;
 $('life-note').textContent=superSaver?'ความคุ้มครองชีวิต 100% ของทุนในปีที่ 0–9 และ 150% ในปีที่ 10–24':endowment?'ความคุ้มครองชีวิต 100% ของทุนประกันตลอดระยะเวลาคุ้มครอง':happy?'ประกันชีวิตตามภาพ: ปีที่ 0–1 = 110%, ปีที่ 2–3 = 220%, ปีที่ 4–5 = 330%, ปีที่ 6–7 = 440%, ปีที่ 8–19 = 550% ของทุนประกัน':guaranteed?'ประกันชีวิตตามภาพ: 100%, 200%, 300%, 400%, 500% และ 600% ของทุนประกันตามลำดับปีที่ 0–5 จากนั้นคงที่ 600% ถึงก่อนครบสัญญา':originalText['life-note'];
 $('maturity-note').textContent=superSaver?'เงินครบสัญญาปีที่ 25 = 150% ของทุนประกัน':endowment?'เงินครบสัญญาปีที่ 20 = 100% ของทุนประกัน':happy?'เงินครบสัญญาปีที่ 20 = 520% ของทุนประกัน':guaranteed?'เงินครบสัญญาปีที่ 15 = 606% ของทุนประกัน':originalText['maturity-note'];
 $('table-note').textContent=superSaver?'ชำระเบี้ย 16 ปี ที่ปี0–15 คุ้มครอง25ปี รับเงินคืนเมื่อครบปี1–10 ปีละ1% ปี11–20 ปีละ1.5% และปี21–24 ปีละ2% ของทุน ปี25รับเงินครบสัญญา150% ของทุน ไม่บวกเงินคืนซ้ำในปีครบสัญญา':endowment?'ชำระเบี้ย 14 ปี ที่ปี 0–13 คุ้มครอง 20 ปี ไม่มีเงินคืนระหว่างสัญญา รับเงินครบสัญญา 100% ของทุนเมื่อครบปีที่ 20 · เงินปันผลเป็นไปตามการจัดสรรของบริษัท จำนวนเงินยังไม่รวมในยอดคำนวณ':happy?'ปีที่ 0 คือเริ่มสัญญา ชำระเบี้ยที่ปี 0–9 รวม 10 ปี โดยคอลัมน์เบี้ยประกันและเบี้ยสะสมรวมทุกงวดต่อปี รับเงินคืน 10% ของทุนทุกปีเมื่อครบปี 1–19 และรับเงินครบสัญญา 520% ของทุนในปีที่ 20 คอลัมน์เงินคืนตามสัญญารวมเงินคืนระหว่างสัญญาและเงินครบสัญญา':guaranteed?'ปีที่ 0 คือเริ่มสัญญา ชำระเบี้ยรายปีที่ปี 0–5 รวม 6 ครั้ง รับเงินคืน 6% ของทุนทุกปีเมื่อครบปี 1–14 และรับเงินครบสัญญา 606% ของทุนในปีที่ 15 คอลัมน์เงินคืนตามสัญญารวมเงินคืนระหว่างสัญญาและเงินครบสัญญา ตัวอย่างอายุเริ่ม 35 ปี ครบสัญญาอายุ 50 ปี':originalText['table-note'];$('index-fields').hidden=!$('simulate').checked;
 const annualMode=$('return-mode').value==='annual';$('annual-return-field').hidden=!annualMode;$('index-level-fields').hidden=annualMode;
 $('amount-label').textContent=mode==='sum'?'ทุนประกัน (บาท)':(modal?`เบี้ยประกัน${$('frequency').selectedOptions?.[0]?.textContent||'รายปี'} (บาท/งวด)`:'เบี้ยประกันรายปี (บาท)');
 try{const r=calculateSavings({plan:$('plan').value,gender:$('gender').value,age:$('age').value,atLeast30Days:$('days').checked,mode:mode,frequency:modal?$('frequency').value:'annual',amount:$('amount').value,simulate:$('simulate').checked,returnMode:$('return-mode').value,annualReturn:$('annual-return').value,indexStart:$('index-start').value,indexEnd:$('index-end').value,fxStart:$('fx-start').value,fxEnd:$('fx-end').value});current=r;
 $('error').hidden=true;$('print').disabled=false;$('copy').disabled=false;
 $('selected-plan').textContent=r.plan.name;
 $('dividend-heading').textContent=savingsDividendLabel(r);
 $('rate-note').textContent=`${guaranteed?'':'ทุนขั้นต่ำ 20,000 บาท · '}อัตรา ${r.rate} บาทต่อทุน 1,000 บาท`;
 const metrics=[['ทุนประกัน',r.sum],[modal?`เบี้ยประกัน${r.frequency.label} (ต่องวด)`:'เบี้ยประกันรายปี',r.premium],[`เบี้ยรวม ${payYears} ปี`,r.totalPremium],[endowment?'เงินคืนระหว่างสัญญา':`เงินคืนรวม ${cashYears} ครั้ง`,r.cashTotal],['เงินครบสัญญา',r.maturity],['ผลประโยชน์การันตีรวม',r.guaranteedTotal]];
 if(modal&&r.frequency.payments>1)metrics.splice(2,0,['เบี้ยรวมทุกงวดต่อปี',r.annualPremium]);
 if(r.indexBenefit!==null)metrics.push(['ผลตอบแทนดัชนีคาดการณ์ (ไม่การันตี)',r.indexBenefit],['ยอดรับรวมคาดการณ์ (รวมเงินคืน)',r.projectedTotal],['ส่วนต่างยอดรับคาดการณ์กับเบี้ยรวม',r.projectedGain]);
 $('metrics').innerHTML=metrics.map(([label,value])=>`<div class="card saving-metric"><p>${label}</p><strong>${money(value)}</strong><small>บาท</small></div>`).join('');
 $('benefits').textContent=superSaver?`รับเงินคืนปีที่ 1–10 ปีละ 1% (${money(r.sum*.01)} บาท) ปีที่ 11–20 ปีละ 1.5% (${money(r.sum*.015)} บาท) และปีที่ 21–24 ปีละ 2% (${money(r.sum*.02)} บาท) · ครบสัญญาปีที่ 25 รับ 150% (${money(r.maturity)} บาท)`:endowment?`ชำระเบี้ย 14 ปี คุ้มครอง 20 ปี · ความคุ้มครองชีวิต 100% ของทุน · ครบสัญญารับ 100% ของทุน (${money(r.maturity)} บาท) · เงินปันผลขึ้นอยู่กับการจัดสรรของบริษัท ไม่รับประกันจำนวนเงิน`:happy?`รับเงินคืน 10% ของทุนประกัน (${money(r.cash)} บาท) ทุกปีเมื่อครบปีที่ 1–19 รวม 19 ครั้ง · ครบสัญญาปีที่ 20 รับ 520% ของทุนประกัน (${money(r.maturity)} บาท)`:guaranteed?`รับเงินคืน 6% ของทุนประกัน (${money(r.cash)} บาท) ทุกปีเมื่อครบปีที่ 1–14 รวม 14 ครั้ง · ครบสัญญาปีที่ 15 รับ 606% ของทุนประกัน (${money(r.maturity)} บาท)`:`รับเงินคืน ${(r.plan.cashRate*100)}% ของทุนประกัน (${money(r.cash)} บาท) ณ สิ้นปีที่ 2, 4, 6, 8, 10, 12 และ 14 · PR ${r.plan.pr*100}%`;
 $('index-result').hidden=r.indexBenefit===null;
 $('index-result').textContent=r.indexBenefit===null?'':`${r.assumedAnnualReturn===null?'คำนวณจากระดับดัชนีที่ระบุ':`สมมติดัชนีเติบโตเฉลี่ย ${r.assumedAnnualReturn}% ต่อปี ตามสมมติฐานเทียบตัวอย่างเอกสาร`}${r.projectedIndexEnd===null?'':` · ดัชนี 230 → ${money(r.projectedIndexEnd)}`} · PR ${r.plan.pr*100}% · อัตราแลกเปลี่ยน ${$('fx-start').value} → ${$('fx-end').value} บาท/USD · ผลตอบแทนดัชนีคาดการณ์ ${money(r.indexBenefit)} บาท · ยอดรับรวมคาดการณ์ ${money(r.projectedTotal)} บาท (ไม่การันตีส่วนดัชนี)`;
 $('schedule-body').innerHTML=r.rows.map(row=>`<tr><td><span class="age-number">${row.age}</span><small class="phase">${elapsedYearLabel(r,row)}</small>${row.year===term?'<small class="maturity-label">ครบสัญญา</small>':''}</td>${[row.premium,row.paid,row.cash+row.maturity,row.life,...(guaranteed?[]:[row.indexBenefit])].map(value=>`<td>${value===null?'—':money(value)}</td>`).join('')}</tr>`).join('');
 $('summary').value=`TYINSURE | แผนออมทรัพย์\n${r.plan.name}\nเพศ${$('gender').value==='male'?'ชาย':'หญิง'} อายุ ${r.age} ปี\nทุนประกัน ${money(r.sum)} บาท\nชำระ${happy?r.frequency.label:'รายปี'} ${money(r.premium)} บาท${happy?'/งวด':''} นาน ${payYears} ปี คุ้มครอง ${term} ปี${happy?`\nเบี้ยรวมทุกงวดต่อปี ${money(r.annualPremium)} บาท`: ''}\nเบี้ยรวม ${money(r.totalPremium)} บาท\n${guaranteed?'เงินคืนทุกปี':'เงินคืนทุก 2 ปี'} ครั้งละ ${money(r.cash)} บาท รวม ${cashYears} ครั้ง\nเริ่มสัญญาอายุ ${r.age} ปี = ปีที่ 0 · ครบ ${term} ปี อายุ ${r.age+term} ปี\nเงินคืนที่อายุ ${(guaranteed?Array.from({length:cashYears},(_,i)=>i+1):[2,4,6,8,10,12,14]).map(y=>r.age+y).join(', ')} ปี\nเงินครบสัญญา ${money(r.maturity)} บาท\nผลประโยชน์การันตีรวม ${money(r.guaranteedTotal)} บาท${guaranteed?'':`\nPR ${r.plan.pr*100}%`}${r.indexBenefit===null?'':`\n${r.assumedAnnualReturn===null?'ใช้ระดับดัชนีที่ระบุ':`สมมติผลตอบแทนดัชนี ${r.assumedAnnualReturn}% ต่อปี ตามสมมติฐานเทียบตัวอย่างเอกสาร`}${r.projectedIndexEnd===null?'':`\nดัชนีเริ่มต้น 230 → ${money(r.projectedIndexEnd)} (สมมติ 14 ปี 11 เดือนเพื่อเทียบตัวอย่าง ไม่ใช่วันลงทุนจริง)`}\nอัตราแลกเปลี่ยน ${$('fx-start').value} → ${$('fx-end').value} บาท/USD\nผลตอบแทนดัชนีคาดการณ์ ${money(r.indexBenefit)} บาท (ไม่การันตี)\nยอดรับรวมคาดการณ์ ${money(r.projectedTotal)} บาท\nส่วนต่างยอดรับคาดการณ์กับเบี้ยรวม ${money(r.projectedGain)} บาท`}${guaranteed?'':'\nผลตอบแทนตามดัชนีไม่การันตี จ่ายเมื่อมีชีวิตอยู่ครบสัญญาเท่านั้น'}\nเอกสารนี้จัดทำเพื่อเป็นข้อมูลเพื่อใช้ประกอบการตัดสินใจเท่านั้น ไม่ใช่ใบเสนอขาย\nทัก LINE @TYINSURE`;
 if(superSaver)$('summary').value=`TYINSURE | แผนออมทรัพย์\n${r.plan.name}\nเพศ${$('gender').value==='male'?'ชาย':'หญิง'} อายุ ${r.age} ปี\nทุนประกัน ${money(r.sum)} บาท\nชำระ${r.frequency.label} ${money(r.premium)} บาท/งวด นาน16ปี คุ้มครอง25ปี\nเบี้ยรวมทุกงวดต่อปี ${money(r.annualPremium)} บาท\nเบี้ยรวม16ปี ${money(r.totalPremium)} บาท\nเงินคืนปี1–10 ปีละ1% ${money(r.sum*.01)} บาท\nเงินคืนปี11–20 ปีละ1.5% ${money(r.sum*.015)} บาท\nเงินคืนปี21–24 ปีละ2% ${money(r.sum*.02)} บาท\nเงินคืนระหว่างสัญญารวม ${money(r.cashTotal)} บาท\nเงินครบสัญญาปี25 เมื่ออายุ ${r.age+25} ปี ${money(r.maturity)} บาท\nผลประโยชน์การันตีรวม ${money(r.guaranteedTotal)} บาท\nความคุ้มครองชีวิต100% ของทุนในปี0–9 และ150% ในปี10–24\n${SAVINGS_DISCLAIMER}\nทัก LINE @TYINSURE`;
 if(endowment)$('summary').value=`TYINSURE | แผนออมทรัพย์\n${r.plan.name}\nเพศ${$('gender').value==='male'?'ชาย':'หญิง'} อายุ ${r.age} ปี\nทุนประกัน ${money(r.sum)} บาท\nชำระ${r.frequency.label} ${money(r.premium)} บาท/งวด นาน 14 ปี คุ้มครอง 20 ปี\nเบี้ยรวมทุกงวดต่อปี ${money(r.annualPremium)} บาท\nเบี้ยรวม 14 ปี ${money(r.totalPremium)} บาท\nความคุ้มครองชีวิต 100% ของทุนประกัน\nไม่มีเงินคืนระหว่างสัญญา\nเงินครบสัญญาเมื่ออายุ ${r.age+20} ปี ${money(r.maturity)} บาท\nเงินปันผลขึ้นกับการจัดสรรของบริษัท ไม่รับประกันจำนวนเงิน และยังไม่รวมในยอดคำนวณ\n${SAVINGS_DISCLAIMER}\nทัก LINE @TYINSURE`;
 }catch(e){$('dividend-heading').textContent='เงินปันผลหากได้ผลตอบแทน';current=null;$('error').hidden=false;$('error').textContent=e.message;$('rate-note').textContent=guaranteed?'กรุณาตรวจสอบข้อมูล':'ทุนประกันขั้นต่ำ 20,000 บาท';$('metrics').replaceChildren();$('schedule-body').replaceChildren();$('selected-plan').textContent='';$('benefits').textContent='';$('index-result').hidden=true;$('summary').value='';$('print').disabled=true;$('copy').disabled=true;}
 $('copy-status').textContent='';
 $('excel').disabled=$('pdf').disabled=!current||exporting;
}
$('savings-form').addEventListener('submit',e=>e.preventDefault());$('savings-form').addEventListener('input',render);$('savings-form').addEventListener('change',render);
$('print').addEventListener('click',()=>{render();if(current)window.print();});
window.addEventListener('beforeprint',render);
$('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('summary').value);$('copy-status').textContent=' คัดลอกแล้ว';}catch{$('summary').select();$('copy-status').textContent=' เลือกข้อความแล้ว กรุณาคัดลอก';}});
render();

for(const value of ['sum','premium'])$('mode-'+value).addEventListener('click',()=>{mode=value;for(const key of ['sum','premium']){$('mode-'+key).classList.toggle('active',key===value);$('mode-'+key).setAttribute('aria-selected',String(key===value));}render();});
async function download(kind){
 if(exporting)return;render();if(!current)return;
 const result=current,options={mode,gender:$('gender').value,fxStart:$('fx-start').value,fxEnd:$('fx-end').value};
 exporting=true;$('excel').disabled=$('pdf').disabled=true;$('export-status').textContent='กำลังสร้างไฟล์…';
 try{
  const blob=await(kind==='pdf'?createSavingsPDF(result,options):createSavingsExcel(result,options));
  const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`TYINSURE_Savings_${result.plan.product==='super2516'?'SuperSaver_25-16':result.plan.product==='endowment2014'?'Endowment_20-14':result.plan.product==='happy2010'?'HappyReturn_20-10':`15-6_${result.plan.guaranteed?'Guaranteed':result.plan.pr===1?'Pro':'Global'}`}_age${result.age}.${kind==='pdf'?'pdf':'xlsx'}`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('export-status').textContent='สร้างไฟล์เรียบร้อยแล้ว';
 }catch(e){$('export-status').textContent='สร้างไฟล์ไม่สำเร็จ: '+e.message;}finally{exporting=false;$('excel').disabled=$('pdf').disabled=!current;}
}
$('excel').addEventListener('click',()=>download('excel'));$('pdf').addEventListener('click',()=>download('pdf'));
